String num = String.valueOf(N);
int len = num.length();
int[][][] dp = new int[len][2][...];   // dimensions depend on problem
// fill with -1 (not computed yet)

int solve(int pos, int tight, int state, ...) {

    // base case — all digits placed
    if (pos == len) {
        return isValid(state) ? 1 : 0;
    }

    // already computed
    if (dp[pos][tight ? 1 : 0][state] != -1)
        return dp[pos][tight ? 1 : 0][state];

    int limit = tight ? (num.charAt(pos) - '0') : 9;
    int result = 0;

    for (int digit = 0; digit <= limit; digit++) {
        boolean newTight = tight && (digit == limit);
        result += solve(pos + 1, newTight, newState(state, digit), ...);
    }

    return dp[pos][tight ? 1 : 0][state] = result;
}

int solve(int pos, int tight, boolean started, int state) {

    if (pos == len) {
        return started ? (isValid(state) ? 1 : 0) : 0;
    }

    int limit = tight ? (num.charAt(pos) - '0') : 9;
    int result = 0;

    for (int digit = 0; digit <= limit; digit++) {
        if (!started && digit == 0) {
            // still in leading zeros
            result += solve(pos + 1, tight && (digit == limit), false, initialState);
        } else {
            // actual digit placed
            result += solve(pos + 1, tight && (digit == limit), true, newState(state, digit));
        }
    }

    return result;
}
